import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        int n = r.nextInt();
        long target = r.nextLong();
        long[] power = new long[n];
        for (int i = 0; i < n; i++) power[i] = r.nextLong();
        long[] one = new long[n], two = new long[n];
        int c1 = 0, c2 = 0;
        for (int i = 0; i < n; i++) {
            int cost = r.nextInt();
            if (power[i] <= 0) continue;  // never worth paying for
            if (cost == 1) one[c1++] = power[i]; else two[c2++] = power[i];
        }
        if (target <= 0) { System.out.println(0); return; }
        one = Arrays.copyOf(one, c1);
        two = Arrays.copyOf(two, c2);
        Arrays.sort(one);  // ascending; take from the end for descending order
        Arrays.sort(two);
        long[] prefix = new long[c2 + 1];
        for (int j = 0; j < c2; j++) prefix[j + 1] = prefix[j] + two[c2 - 1 - j];
        long supplied = 0, best = Long.MAX_VALUE;
        for (int i = 0; i <= c1; i++) {
            long need = Math.max(0, target - supplied);
            int lo = 0, hi = c2 + 1;  // first prefix >= need
            while (lo < hi) { int mid = (lo + hi) >>> 1; if (prefix[mid] < need) lo = mid + 1; else hi = mid; }
            if (lo <= c2) best = Math.min(best, i + 2L * lo);
            if (i < c1) supplied += one[c1 - 1 - i];
        }
        System.out.println(best == Long.MAX_VALUE ? -1 : best);
    }
}


final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

