import (
	"bufio"
	"fmt"
	"os"
	"slices"
	"sort"
)

func main() {
	n, target := readInt(), readInt()
	power := make([]int, n)
	for i := range power {
		power[i] = readInt()
	}
	var one, two []int
	for i := 0; i < n; i++ {
		cost := readInt()
		if power[i] <= 0 { // never worth paying for
			continue
		}
		if cost == 1 {
			one = append(one, power[i])
		} else {
			two = append(two, power[i])
		}
	}
	if target <= 0 {
		fmt.Println(0)
		return
	}
	slices.Sort(one)
	slices.Reverse(one)
	slices.Sort(two)
	slices.Reverse(two)
	prefix := []int{0}
	for _, p := range two {
		prefix = append(prefix, prefix[len(prefix)-1]+p)
	}
	supplied, best := 0, -1
	for i := 0; i <= len(one); i++ {
		j := sort.SearchInts(prefix, max(0, target-supplied))
		if j < len(prefix) && (best < 0 || i+2*j < best) {
			best = i + 2*j
		}
		if i < len(one) {
			supplied += one[i]
		}
	}
	fmt.Println(best)
}

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readToken() string {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	var buf []byte
	for err == nil && b > ' ' {
		buf = append(buf, b)
		b, err = reader.ReadByte()
	}
	return string(buf)
}

func readInt() int {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, err = reader.ReadByte()
	}
	r := 0
	for err == nil && b >= '0' && b <= '9' {
		r = r*10 + int(b-'0')
		b, err = reader.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}
